client:
harness.define({
  name: "daily-quote",
  apply: (ctx) => {
    const ui = ctx.get("uiSlots");
    const quotes = ["把今天写下来，明天就有迹可循。", "慢一点，也是在前进。", "笔记是第二大脑的抽屉。"];
    ui.register({
      id: "daily-quote",
      slot: "sidebar.footer.action",
      kind: "list",
      order: 10,
      component: harness.createElement(
        "button",
        {
          type: "button",
          title: "今日一句",
          "aria-label": "今日一句",
          className: "flex h-7 w-7 items-center justify-center rounded-full text-shell-label-secondary hover:bg-shell-row-hover",
          onClick: () => {
            const index = Math.floor(Math.random() * quotes.length);
            window.alert(quotes[index]);
          },
        },
        "✨",
      ),
    });
  },
});
